dtsPropsFor.AppLayout:
/** Page content, rendered inside the shell's 1120px main column. */
  children: React.ReactNode;
  /** The signed-in household member, named in the top bar. */
  user: { id: string; username: string };
  /** 17px/700 line in the top bar. */
  title: string;
  /** 12px dimmed line under it — the screen's context. */
  subtitle?: string;
  /** Where the back chevron goes. Omit on the three top-level screens. */
  backHref?: string;
  /** Which bottom-nav entry is lit, and what the FAB does. */
  tab?: 'catalog' | 'categories' | 'users';
  /** false on form screens: hides the bottom bar and the FAB. */
  chrome?: boolean;
  /** Overrides the FAB target — the catalog FAB prefills the open category. */
  fabHref?: string;

dtsPropsFor.CategoryVisual:
/** Enough of a category to resolve the fallback. */
  category: { name: string; icon: string | null; mainImage: string | null; firstItemImage?: string | null };
  /** `tile` fills a catalog tile's square; `thumb` is the 52px card square. */
  variant?: 'tile' | 'thumb';

dtsPropsFor.UsersManager:
/** Household members to list. Never carries passwordHash. */
  initialUsers: Array<{ id: string; username: string; createdAt: Date }>;
  /** Id of the signed-in user — that row is badged and cannot be deleted. */
  currentUserId: string;

dtsPropsFor.ItemForm:
/** Categories offered as chips. */
  categories: Array<{ id: string; name: string; icon: string | null; mainImage: string | null; itemCount: number; firstItemImage: string | null; createdAt: Date; updatedAt: Date }>;
  /** The item being edited. Omit to render the add form. */
  item?: { id: string; categoryId: string; categoryName: string; description: string | null; mainImage: string; additionalImages: string[]; createdById: string | null; createdByName: string; createdAt: Date; updatedAt: Date };
  /** Preselected category when adding from inside one. */
  initialCategoryId?: string;

dtsPropsFor.ConfirmSheet:
opened: boolean;
  onClose: () => void;
  /** "Usunąć kategorię?", "Usunąć konto?", … */
  title: string;
  /** What disappears and whether it comes back. */
  message: React.ReactNode;
  /** Defaults to "Usuń". */
  confirmLabel?: string;
  onConfirm: () => void;
  loading?: boolean;

dtsPropsFor.FormActionBar:
/** Where "Anuluj" goes — the same screen the back chevron returns to. */
  cancelHref: string;
  /** Copy of the primary action: "Utwórz kategorię", "Zapisz zmiany", … */
  submitLabel: string;
  loading?: boolean;
  disabled?: boolean;

dtsPropsFor.AuthScreen:
title: string;
  subtitle: string;
  children: React.ReactNode;

dtsPropsFor.ImageDropzone:
/** Called with the accepted files each time photos are dropped or picked. */
  onDrop: (files: File[]) => void;
  /** Bold line inside the dropzone. Omit for a caption-only drop target. */
  title?: string;
  /** Dimmed line under the title. */
  hint?: string;
  disabled?: boolean;
  /** Which glyph to show at rest. */
  idleIcon?: 'photo' | 'plus' | 'camera';
  /** Glyph edge length in px. */
  iconSize?: number;
  /** Minimum height of the drop target in px. */
  minHeight?: number;
  maxFiles?: number;
  /** Bottom margin, as a Mantine spacing token. */
  mb?: string;
  /** Hints the rear camera on mobile. */
  capture?: boolean;
  /** `panel` is a form field; `tile` is the bare square "+" in a photo grid. */
  variant?: 'panel' | 'tile';

dtsPropsFor.ImageLightboxModal:
opened: boolean;
  onClose: () => void;
  /** Stored image filenames, not URLs. */
  images: string[];
  /** Which image to open on. Defaults to 0. */
  initialIndex?: number;
  /** Shown in the modal header. */
  title?: string;
